      SUBROUTINE POSSIMC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM0D.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM6.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8F.CIN'      INCLUDE 'ELM8G.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INDBND.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'LXRAN.CIN'      INCLUDE 'R0P.CIN'      INCLUDE 'STEPT1.CIN'CC     LOCAL VARIABLESC      INTEGER         IMIS, J, NUPS, TYPESC      TYPEC = TYPE      CALL DEPIC2C      IF (ALIGN .AND. RMTX .AND. TYPE .NE. 8) THEN        BEFORE = .TRUE.C        IF (.NOT. R0P) THEN          DO 50 IR = 2, 3          NUPS = NIU(IR)          IF (NUPS .NE. 0) THEN            DO 40 NAL = 1, NUPS            IF (NAL .GT. 10) THEN              WRITE (NOUT,9001) 9001         FORMAT (' *** TOO MANY NESTED MISALIGNMENTS')              FLUSHL = .TRUE.              GO TO 200            ENDIF            TYPES = TYPE            TYPE = 6            TYPEC = 8            NN = NUPS - NAL + 1            NMIS = NIM(IR,NN)            IMIS = ISTOR(NMIS)            TYT = INT(DATA(IMIS+7))            LFM = TYT/100            LXRAN = LFM .GE. 2            DO 25 J = 1, 25   25       IPTOJB(J) = IPTOJ(J)            CALL SKETCH(NMIS)            IF (NV3 .GE. 1) THEN              CALL DERIVE            ELSE              CALL ELICIT              IF (.NOT. LSTEPN) THEN                CALL POSTER                CALL MPRINT              ENDIF            ENDIF            IF (FLUSHL) GO TO 200            IF (TYPE .LE. 0) GO TO 200            TYPE = TYPES            DO 30 J = 1, 25   30       IPTOJ(J) = IPTOJB(J)   40       CONTINUE          ENDIF   50     CONTINUE        ENDIFC        CALL FIND8        IR = 1        JA = 0        KA = 0        NUPS = NUP(1)C        IF (NUPS .NE. 0) THEN          DO 80 NAL = 1, NUPS          IF (NAL .GT. 10) THEN            WRITE (NOUT,9001)            FLUSHL = .TRUE.            GO TO 200          ENDIF          TYPES = TYPE          TYPE = 6          TYPEC = 8          NN = NUPS - NAL + 1          NMIS = NIM(IR,NN)          IMIS = ISTOR(NMIS)          TYT = INT(DATA(IMIS+7))          LFM = TYT/100          LXRAN = LFM .GE. 2          DO 60 J = 1, 25   60     IPTOJB(J) = IPTOJ(J)          CALL SKETCH(NMIS)          IF (NV3 .GE. 1) THEN            CALL DERIVE          ELSE            CALL ELICIT            IF (.NOT. LSTEPN) THEN              CALL POSTER              CALL MPRINT            ENDIF          ENDIF          IF (FLUSHL) GO TO 200          IF (TYPE .LE. 0) GO TO 200          TYPE = TYPES          DO 70 J = 1, 25   70     IPTOJ(J) = IPTOJB(J)   80     CONTINUEC        ENDIF      ENDIFC  200 RETURN      END